//! ====================================================================
//!  Rust Tree CLI Utility for Windows
//!  Generated by Rust Tree Command Builder
//! ====================================================================
//!
//!  このプログラムは、指定したディレクトリの構造をツリー形式で出力するCLIツールです。
//!  外部の重いライブラリ（clapなど）に依存せず、Rustの標準ライブラリ（std）のみで
//!  軽量・高速に動作するように記述されています。

mod icon;

use std::env;
use std::fs;
use std::path::{Path, PathBuf};

/// 出力フォーマットの定義
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OutputFormat {
    Text,
    Json,
    Xml,
}

/// ツールでサポートする設定オプション
#[derive(Debug, Clone)]
struct TreeConfig {
    target_path: PathBuf,
    show_icons: bool,
    show_sizes: bool,
    show_dir_sizes: bool,
    show_hidden: bool,
    max_depth: usize,
    exclude_patterns: Vec<String>,
    classic_mode: bool,
    output_format: OutputFormat,
}

impl Default for TreeConfig {
    fn default() -> Self {
        Self {
            target_path: PathBuf::from("."),
            show_icons: true,
            show_sizes: true,
            show_dir_sizes: false,
            show_hidden: false,
            max_depth: 0,
            exclude_patterns: vec!["target", "node_modules", ".git"]
                .into_iter()
                .map(String::from)
                .collect(),
            classic_mode: false,
            output_format: OutputFormat::Text,
        }
    }
}

/// 機械可読フォーマット出力用のメモリ内ツリーノード構造体
#[derive(Debug, Clone)]
struct TreeNode {
    name: String,
    path: String,
    is_dir: bool,
    size: u64,
    children: Vec<TreeNode>,
}

fn main() {
    // Windows 10/11のプロンプトでANSIエスケープカラーを有効化
    #[cfg(windows)]
    enable_ansi_support();

    // 1. 引数の解析
    let args: Vec<String> = env::args().collect();
    let mut config = TreeConfig::default();

    if let Err(err) = parse_arguments(&args, &mut config) {
        eprintln!("【エラー】: {}", err);
        print_help();
        std::process::exit(1);
    }

    // ターゲットが存在するか検証
    if !config.target_path.exists() {
        eprintln!(
            "【エラー】: 指定されたパスが存在しません: {:?}",
            config.target_path
        );
        std::process::exit(1);
    }

    // 2. 出力処理の分岐
    match config.output_format {
        OutputFormat::Text => {
            println!("{}", format_root_line(&config));

            let mut dir_count = 0;
            let mut file_count = 0;

            // 再帰的にツリーを描画
            print_tree(
                &config.target_path,
                0,
                &mut Vec::new(),
                &config,
                &mut dir_count,
                &mut file_count,
            );

            // 最終集計の出力
            println!();
            if config.classic_mode {
                println!("{} directories, {} files", dir_count, file_count);
            } else {
                println!(
                    "\x1b[36m{} directories, {} files\x1b[0m",
                    dir_count, file_count
                );
            }
        }
        OutputFormat::Json => {
            let mut dir_count = 0;
            let mut file_count = 0;
            let root = build_tree_node(
                &config.target_path,
                0,
                &config,
                &mut dir_count,
                &mut file_count,
            );
            println!("{}", serialize_json(&root, dir_count, file_count));
        }
        OutputFormat::Xml => {
            let mut dir_count = 0;
            let mut file_count = 0;
            let root = build_tree_node(
                &config.target_path,
                0,
                &config,
                &mut dir_count,
                &mut file_count,
            );
            println!("{}", serialize_xml(&root, dir_count, file_count));
        }
    }
}

/// 引数を手動で解析 (軽量化のため標準ライブラリのみを使用)
fn parse_arguments(args: &[String], config: &mut TreeConfig) -> Result<(), String> {
    let mut i = 1;
    let mut path_set = false;

    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-v" | "--version" => {
                print_version();
                std::process::exit(0);
            }
            "--help-icons" | "--icons-help" => {
                icon::print_icons_help();
                std::process::exit(0);
            }
            "-i" | "--icons" => {
                config.show_icons = true;
            }
            "-I" | "--no-icons" => {
                config.show_icons = false;
            }
            "-s" | "--sizes" => {
                config.show_sizes = true;
            }
            "-S" | "--no-sizes" => {
                config.show_sizes = false;
            }
            "-c" | "--classic" => {
                config.classic_mode = true;
                config.show_icons = false;
                config.show_sizes = false;
            }
            "-D" | "--dir-sizes" | "--du" => {
                config.show_dir_sizes = true;
            }
            "-a" | "--all" => {
                config.show_hidden = true;
            }
            "--json" => {
                config.output_format = OutputFormat::Json;
            }
            "--xml" => {
                config.output_format = OutputFormat::Xml;
            }
            "-d" | "--depth" => {
                if i + 1 < args.len() {
                    let depth_str = &args[i + 1];
                    config.max_depth = depth_str
                        .parse::<usize>()
                        .map_err(|_| format!("無効な深度が指定されました: {}", depth_str))?;
                    i += 1;
                } else {
                    return Err("深度の値が指定されていません (-d <DEPTH>)".to_string());
                }
            }
            "-e" | "--exclude" => {
                if i + 1 < args.len() {
                    let excludes_str = &args[i + 1];
                    config.exclude_patterns = excludes_str
                        .split(',')
                        .map(|s| s.trim().to_string())
                        .filter(|s| !s.is_empty())
                        .collect();
                    i += 1;
                } else {
                    return Err("除外パターンが指定されていません (-e <PATTERNS>)".to_string());
                }
            }
            _ => {
                if arg.starts_with('-') {
                    return Err(format!("不明なオプションです: {}", arg));
                } else if !path_set {
                    config.target_path = PathBuf::from(arg);
                    path_set = true;
                } else {
                    return Err(format!("重複したターゲットパス指定です: {}", arg));
                }
            }
        }
        i += 1;
    }

    Ok(())
}

